"use client";

import { useCallback, useState } from "react";
import { Community } from "@/components/community";
import { DownloadModal } from "@/components/download-modal";
import { DownloadSelector } from "@/components/download-selector";
import { Features } from "@/components/features";
import { Footer } from "@/components/footer";
import { Header } from "@/components/header";
import { Hero } from "@/components/hero";
import { News } from "@/components/news";
import { Releases } from "@/components/releases";
import {
  DownloadConfig,
  getIsoFilename,
  ReleaseBranch,
} from "@/lib/download";

const initialConfig: DownloadConfig = {
  branch: "stable",
  architecture: "amd64",
  media: "netinst",
};

export default function HomePage() {
  const [config, setConfig] = useState(initialConfig);
  const [downloadOpen, setDownloadOpen] = useState(false);
  const closeDownload = useCallback(() => setDownloadOpen(false), []);

  function selectRelease(branch: ReleaseBranch) {
    setConfig((current) => ({ ...current, branch }));
    setDownloadOpen(true);
  }

  return (
    <>
      <Header />
      <main className="flex-grow">
        <Hero onOpenDownload={() => setDownloadOpen(true)} />
        <DownloadSelector
          config={config}
          onConfigChange={setConfig}
          onOpenDownload={() => setDownloadOpen(true)}
        />
        <Features />
        <Releases config={config} onSelectBranch={selectRelease} />
        <News />
        <Community />
      </main>
      <Footer />
      <DownloadModal
        isOpen={downloadOpen}
        isoName={getIsoFilename(config)}
        onClose={closeDownload}
      />
    </>
  );
}
