"use client";

import { type FormEvent, useEffect, useState } from "react";
import { Download, Menu, Moon, Search, Sun, X } from "lucide-react";
import { DebianMark } from "@/components/debian-mark";

const links = [
  { href: "#download", label: "Download" },
  { href: "#features", label: "Why Debian" },
  { href: "#releases", label: "Releases" },
  { href: "#news", label: "News" },
  { href: "#community", label: "Community & Docs" },
];

export function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [isDark, setIsDark] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchMessage, setSearchMessage] = useState("");

  useEffect(() => {
    const savedTheme = window.localStorage.getItem("theme");
    const dark = savedTheme !== "light";
    document.documentElement.classList.toggle("dark", dark);
    document.documentElement.classList.toggle("light", !dark);
    setIsDark(dark);
  }, []);

  function toggleTheme() {
    const nextIsDark = !isDark;
    document.documentElement.classList.toggle("dark", nextIsDark);
    document.documentElement.classList.toggle("light", !nextIsDark);
    window.localStorage.setItem("theme", nextIsDark ? "dark" : "light");
    setIsDark(nextIsDark);
  }

  function searchPage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const query = searchQuery.trim().toLocaleLowerCase();

    if (!query) {
      setSearchMessage("Enter a search term.");
      return;
    }

    const matchingSection = Array.from(
      document.querySelectorAll<HTMLElement>("main section"),
    ).find((section) =>
      section.innerText.toLocaleLowerCase().includes(query),
    );

    if (!matchingSection) {
      setSearchMessage(`No sections found for “${searchQuery.trim()}”.`);
      return;
    }

    const heading =
      matchingSection.querySelector("h1, h2, h3")?.textContent?.trim() ??
      "matching section";
    matchingSection.scrollIntoView({ behavior: "smooth", block: "start" });
    setSearchMessage(`Showing ${heading}.`);
  }

  return (
    <header className="sticky top-0 z-40 w-full border-b border-slate-800/80 bg-slate-950/80 backdrop-blur-md dark:border-slate-800/80 dark:bg-slate-950/80 light:border-slate-200 light:bg-white/80">
      <div className="flex h-20 w-full items-center justify-between gap-3 px-3 sm:gap-5 sm:px-5 lg:gap-6 lg:px-8">
        <a href="#" className="group flex shrink-0 items-center gap-3" aria-label="Debian home">
          <DebianMark className="h-10 w-10 text-debian transition-transform duration-500 group-hover:rotate-6 group-hover:scale-110" />
          <span className="flex flex-col">
            <span className="text-xl font-bold leading-none tracking-tight text-white dark:text-white light:text-slate-900">
              debian
            </span>
            <span className="mt-0.5 text-[10px] font-semibold uppercase tracking-widest text-debian">
              Universal OS
            </span>
          </span>
        </a>

        <nav className="hidden items-center gap-4 text-sm font-medium lg:flex xl:gap-8" aria-label="Main navigation">
          {links.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className="text-slate-300 transition-colors hover:text-debian dark:text-slate-300 light:text-slate-600"
            >
              {link.label}
            </a>
          ))}
        </nav>

        <div className="ml-auto flex min-w-0 items-center gap-2 sm:gap-3">
          <form
            role="search"
            onSubmit={searchPage}
            className="flex min-w-0 items-center"
          >
            <label htmlFor="site-search" className="sr-only">
              Search this page
            </label>
            <div className="flex h-10 w-24 items-center gap-2 rounded-xl border border-slate-800 bg-slate-900/50 px-3 text-slate-400 transition-colors focus-within:border-debian sm:w-48 lg:w-56 dark:border-slate-800 dark:bg-slate-900/50 dark:text-slate-400 light:border-slate-200 light:bg-slate-100 light:text-slate-600">
              <Search className="h-4 w-4 shrink-0" aria-hidden="true" />
              <input
                id="site-search"
                type="search"
                value={searchQuery}
                onChange={(event) => {
                  setSearchQuery(event.target.value);
                  setSearchMessage("");
                }}
                placeholder="Search"
                className="min-w-0 flex-1 bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-500 dark:text-slate-100 light:text-slate-800 light:placeholder:text-slate-500"
              />
            </div>
            <button type="submit" className="sr-only">
              Search
            </button>
            <span className="sr-only" role="status" aria-live="polite">
              {searchMessage}
            </span>
          </form>
          <button
            type="button"
            onClick={toggleTheme}
            aria-label={`Switch to ${isDark ? "light" : "dark"} theme`}
            className="rounded-xl border border-slate-800 bg-slate-900/50 p-2 text-slate-400 transition-all hover:text-white dark:border-slate-800 dark:bg-slate-900/50 dark:hover:text-white light:border-slate-200 light:bg-slate-100 light:hover:text-slate-900"
          >
            {isDark ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
          </button>
          <button
            type="button"
            onClick={() => setMenuOpen((open) => !open)}
            aria-label={menuOpen ? "Close mobile menu" : "Open mobile menu"}
            aria-expanded={menuOpen}
            className="rounded-xl p-2 text-slate-600 hover:text-slate-900 focus:outline-none md:hidden dark:text-slate-400 dark:hover:text-white light:text-slate-600 light:hover:text-slate-900"
          >
            {menuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </button>
        </div>
      </div>

      {menuOpen && (
        <nav
          className="space-y-3 border-b border-slate-800 bg-slate-950/95 px-4 pb-6 pt-2 dark:bg-slate-950/95 light:border-slate-200 light:bg-white md:hidden"
          aria-label="Mobile navigation"
        >
          {links.map((link) => (
            <a
              key={link.href}
              href={link.href}
              onClick={() => setMenuOpen(false)}
              className="block py-2 text-base font-medium text-slate-300 hover:text-debian light:text-slate-700"
            >
              {link.label}
            </a>
          ))}
          <form
            role="search"
            onSubmit={(event) => {
              searchPage(event);
              setMenuOpen(false);
            }}
            className="flex items-center gap-2 py-2"
          >
            <label htmlFor="mobile-site-search" className="sr-only">
              Search this page
            </label>
            <div className="flex h-11 min-w-0 flex-1 items-center gap-2 rounded-xl border border-slate-800 bg-slate-900/50 px-3 text-slate-400 dark:border-slate-800 dark:bg-slate-900/50 light:border-slate-200 light:bg-slate-100 light:text-slate-600">
              <Search className="h-4 w-4 shrink-0" aria-hidden="true" />
              <input
                id="mobile-site-search"
                type="search"
                value={searchQuery}
                onChange={(event) => {
                  setSearchQuery(event.target.value);
                  setSearchMessage("");
                }}
                placeholder="Search this page"
                className="min-w-0 flex-1 bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-500 dark:text-slate-100 light:text-slate-800 light:placeholder:text-slate-500"
              />
            </div>
            <button
              type="submit"
              aria-label="Search this page"
              className="rounded-xl bg-debian p-3 text-white"
            >
              <Search className="h-4 w-4" aria-hidden="true" />
            </button>
          </form>
          <a
            href="#download"
            onClick={() => setMenuOpen(false)}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-debian py-3 font-semibold text-white"
          >
            <Download className="h-5 w-5" />
            <span>Get Debian 13</span>
          </a>
        </nav>
      )}
    </header>
  );
}
